import { headers } from 'next/headers'

interface Analytics {
  views: number
  visitors: number
}

interface Notification {
  id: string
  message: string
}

interface Settings {
  theme: string
}

function getBaseUrl() {
  const headersList = headers()
  const host = headersList.get('host') || 'localhost:3000'
  const protocol = process.env.NODE_ENV === 'development' ? 'http' : 'https'
  return `${protocol}://${host}`
}

async function getDashboardData() {
  const baseUrl = getBaseUrl()

  try {
    const [analytics, notifications, settings] = await Promise.all([
      fetch(`${baseUrl}/api/analytics`).then((r) => r.json() as Promise<Analytics>),
      fetch(`${baseUrl}/api/notifications`).then((r) => r.json() as Promise<Notification[]>),
      fetch(`${baseUrl}/api/settings`).then((r) => r.json() as Promise<Settings>),
    ])

    return { analytics, notifications, settings }
  } catch {
    return {
      analytics: { views: 0, visitors: 0 },
      notifications: [] as Notification[],
      settings: { theme: 'light' },
    }
  }
}

export default async function Dashboard() {
  const { analytics, notifications, settings } = await getDashboardData()

  return (
    <div>
      <h2>Dashboard Content</h2>

      <section>
        <h3>Analytics</h3>
        <p>Views: {analytics.views}</p>
        <p>Visitors: {analytics.visitors}</p>
      </section>

      <section>
        <h3>Notifications</h3>
        {notifications.length === 0 ? (
          <p>No notifications</p>
        ) : (
          <ul>
            {notifications.map((notification) => (
              <li key={notification.id}>{notification.message}</li>
            ))}
          </ul>
        )}
      </section>

      <section>
        <h3>Settings</h3>
        <p>Theme: {settings.theme}</p>
      </section>
    </div>
  )
}

